\label{sec-intro}
Throughout this article, let $n \geq 2$ be an integer, and let $k$ be a subfield of $\mathbb R.$ 
We consider the following problem in $\mathbb R^n,$ which is a generalization of the rational angle bisection problem in $\mathbb R^2$ (see \cite{Hir24}).
\begin{q}\label{q-rat-bisec}
For which $\bm{a},$ $\bm{b} \in k^n$ do the angle bisectors between the two lines with direction vectors $\bm{a}$ and $\bm{b}$ have direction vectors in $k^n$?
\end{q}
We denote the inner product of $\bm{a},$ $\bm{b} \in k^n$ by $\langle\bm{a},\bm{b}\rangle.$
\begin{rmk}
Given two lines, we consider the two angles formed by them, regardless of whether they are acute or not. 
If the bisector of one of the angles between $\bm{a},$ $\bm{b} \in k^n$ has a direction vector $\bm{c} \in k^n,$ then that of the other is perpendicular to $\bm{c}$ and has direction vector $\langle\bm{b},\bm{c}\rangle\bm{a}-\langle\bm{a},\bm{c}\rangle\bm{b} \in k^n.$
\end{rmk}
In the case when $k/\mathbb Q$ is algebraic, let $O_k$ be the integer ring of $k.$ 
In this case, Problem \ref{q-rat-bisec} is reduced to the following problem, which becomes an important problem involving solutions of equations that generalize Pythagorean and negative Pell's equations as discussed later.
\begin{q}\label{q-int-bisec}
For which $\bm{a},$ $\bm{b} \in O_k{}^n$ do the angle bisectors between the two lines with direction vectors $\bm{a}$ and $\bm{b}$ have direction vectors in $O_k{}^n$?
\end{q}
Problem \ref{q-int-bisec} is important in drawing techniques when $n = 2$ and $k = \mathbb Q,$ and has an application to optical engineering when $n = 3$ and $k = \mathbb Q$; that is, we can specify the radiation range and the axis of light with a ratio of integers without the errors arising from approximations of irrational numbers by using a solution to Problem \ref{q-int-bisec}.\par
Let $k^{\times 2} = \{ q^2 \mid q \in k^\times\}.$ 
The following theorem plays an important role in solving Problems \ref{q-rat-bisec} and \ref{q-int-bisec}.
\begin{thm}\label{thm-ang}
Let $\bm{a}$ and $\bm{b}$ be linearly independent vectors of $k^n.$
\begin{enumerate}
\item[{\rm (1)}]
The following conditions are equivalent. 
\begin{enumerate}
\item[{\rm (A1)}]
One of the angle bisectors between the two lines with direction vectors $\bm{a}$ and $\bm{b}$ has direction vector $\bm{c} \in k^n.$
\item[{\rm (A2)}]
One of the angle bisectors between the two hyperplanes with normal vectors $\bm{a}$ and $\bm{b}$ has normal vector $\bm{c} \in k^n.$
\item[{\rm (A3)}]
There exists a vector $\bm{c} \in k^n$ such that 
\begin{equation} 
\langle\bm{a},\bm{c}\rangle ^2|\bm{b}|^2 = \langle\bm{b},\bm{c}\rangle ^2|\bm{a}|^2. \label{eq-star} 
\end{equation}
\item[{\rm (A4)}]
We have 
\[ |\bm{a}|^2 \equiv |\bm{b}|^2 \pmod{k^{\times 2}}.\]
\end{enumerate}
If {\rm (A4)} holds, then $\bm{c}$ in {\rm (A1)}--{\rm (A3)} can be taken as 
\begin{equation} 
\bm{c} = \bm{a}\pm\frac{|\bm{a}|}{|\bm{b}|}\bm{b}. \label{eq-c} 
\end{equation}
\item[{\rm (2)}]
Suppose that $k/\mathbb Q$ is algebraic and $\bm{a} = (a_1,\dots,a_n),$ $\bm{b} = (b_1,\dots,b_n) \in O_k{}^n.$ 
Then the following conditions are equivalent. 
\begin{enumerate}
\item[{\rm (B1)}]
One of the angle bisectors between the two lines with direction vectors $\bm{a}$ and $\bm{b}$ has direction vector $\bm{c} \in O_k{}^n.$
\item[{\rm (B2)}]
One of the angle bisectors between the two hyperplanes with normal vectors $\bm{a}$ and $\bm{b}$ has normal vector $\bm{c} \in O_k{}^n.$
\item[{\rm (B3)}]
There exists a vector $\bm{c} \in O_k{}^n$ such that \eqref{eq-star}. 
\item[{\rm (B4)}]
There exist algebraic integers $a_{n+1},$ $b_{n+1},$ $d \in O_k$ such that $d > 0$ and $(x_1,\dots,x_n,x_{n+1}) =$\\
$(a_1,\dots,a_n,a_{n+1}),$ $(b_1,\dots,b_n,b_{n+1})$ are solutions of 
\begin{equation} 
\sum_{i = 1}^nx_i{}^2 = dx_{n+1}{}^2. \label{eq-pell} 
\end{equation} 
\end{enumerate}
If {\rm (B4)} holds, then $\bm{c}$ in {\rm (B1)}--{\rm (B3)} can be taken as 
\[\bm{c} = b_{n+1}\bm{a}\pm a_{n+1}\bm{b}.\] 
\end{enumerate}
\end{thm}
We prove Theorem \ref{thm-ang} in Section \ref{sec-ang}.
\begin{eg}
Let $\bm{a} = (a_1,\dots,a_n),$ $\bm{b} = (b_1,\dots,b_n) \in k^n.$ 
If there exists a nonnegative number $q \in k$ such that 
\[\{ |b_1|,\dots,|b_n|\} = \{ q|a_1|,\dots,q|a_n|\} \quad\text{or}\quad \{ |a_1|,\dots,|a_n|\} = \{ q|b_1|,\dots,q|b_n|\},\] 
then $\bm{a},$ $\bm{b},$ and $\bm{c} = \bm{a}$ satisfy \eqref{eq-star}. 
We call such a solution of \eqref{eq-star} {\it trivial}.
\end{eg}
Several examples of solutions to Problem \ref{q-int-bisec} in the case when $n = 2$ and $k = \mathbb Q$ are given in \cite{Hir24}. 
Here, we provide a few solutions to Problem \ref{q-int-bisec} derived from nontrivial solutions of \eqref{eq-star} in the case when $n = 3$ and $k = \mathbb Q.$
\begin{eg}
\begin{enumerate}
\item[(1)]
If $\bm{a} = (2,2,1)$ and $\bm{b} = (3,6,2),$ then the angle bisectors between the two lines with direction vectors $\bm{a}$ and $\bm{b}$ have direction vectors $7\bm{a}\pm 3\bm{b},$ since $|\bm{a}| = 3$ and $|\bm{b}| = 7$ imply that $7\bm{a}$ and $3\bm{b}$ span a rhomb (see Figure 1).

\item[(2)]
If $\bm{a} = (1,1,4)$ and $\bm{b} = (3,4,5),$ then the angle bisectors between the two lines with direction vectors $\bm{a}$ and $\bm{b}$ have direction vectors $5\bm{a}\pm 3\bm{b},$ since $|\bm{a}| = 3\sqrt 2$ and $|\bm{b}| = 5\sqrt 2$ imply that $5\bm{a}$ and $3\bm{b}$ span a rhomb.
\end{enumerate}
\end{eg}\par
To provide more solutions to Problem \ref{q-int-bisec} in the case when $k = \mathbb Q,$ we derive a formula for \eqref{eq-pell} in Section \ref{sec-plike}.\par
Next, we apply Theorem \ref{thm-ang} to the geometry of simplices. 
We use the following definition.
\begin{df}
\begin{enumerate}
\item[(1)]
A point $P \in \mathbb R^n$ is said to be {\it $k$-rational} if $P \in k^n.$
\item[(2)]
A polytope is said to be {\it over $k$} if all of its vertices are $k$-rational. 
\item[(3)]
The volume $V$ of a polytope is said to be {\it $k$-rational} if $V \in k.$
\item[(4)]
An $n$-simplex is said to be {\it Heronian over $k$} if the volumes of its $i$-faces are all $k$-rational for each $i \in \{ 1,\dots,n\}.$
\end{enumerate}
\end{df}
\begin{thm}\label{thm-sim}
In $\mathbb R^n,$ given $n$-simplex $A_0A_1\cdots A_n$ over $k,$ let $a_i$ be the volume of the facet opposite to $A_i$ for each $i \in \{ 0,1,\dots,n\}.$ 
The following conditions are equivalent.
\begin{enumerate}
\item[{\rm (S1)}]
The incenter $I$ of $n$-simplex $A_0A_1\cdots A_n$ is $k$-rational.
\item[{\rm (S2)}]
We have 
\begin{equation} 
a_0{}^2 \equiv a_1{}^2 \equiv \cdots \equiv a_n{}^2 \pmod{k^{\times 2}}. \label{eq-rat-sim}
\end{equation} 
\end{enumerate}
If $k/\mathbb Q$ is algebraic, then these conditions are equivalent to the following condition.
\begin{enumerate}
\item[{\rm (S2)${}'$}]
There exists a positive algebraic integer $d \in O_k$ such that 
\begin{equation} 
a_0{}^2 \equiv a_1{}^2 \equiv \cdots \equiv a_n{}^2 \equiv d\pmod{k^{\times 2}}.\label{eq-int-sim}
\end{equation} 
\end{enumerate}
\end{thm}
\begin{rmk}
In \eqref{eq-rat-sim} or \eqref{eq-int-sim}, we have $a_0{}^2,$ $a_1{}^2,$ $\dots,$ $a_n{}^2 \in k^\times$ by the Cayley--Menger formula (see \cite[Section 5, Chapter VIII]{Som58}).
\end{rmk}
\begin{thm}\label{thm-trig}
In $\mathbb R^2,$ given triangle $ABC$ over $k$ with side lengths $BC = a,$ $CA = b,$ and $AB = c,$ inradius $r,$ and exradii $r_A,$ $r_B,$ and $r_C,$ the following conditions are equivalent.
\begin{enumerate}
\item[{\rm (T1)}]
At least one of the incenter $I,$ the excenters $I_A,$ $I_B,$ and $I_C$ relative to $A,$ $B,$ and $C,$ the Gergonne point $Ge,$ and the Nagel point $Na$ of triangle $ABC$ is $k$-rational.
\item[{\rm (T2)}]
We have 
\begin{equation} 
a^2 \equiv b^2 \equiv c^2 \pmod{k^{\times 2}}. \label{eq-trig} 
\end{equation} 
\end{enumerate}
If these equivalent conditions hold, then all of $I,$ $I_A,$ $I_B,$ $I_C,$ $Ge,$ and $Na$ are $k$-rational, and triangle $ABC$ can be obtained by scaling a Heronian triangle over $k$ by a factor $q\sqrt d$ for some positive numbers $d,$ $q \in k,$ and $a^2,$ $b^2,$ $c^2,$ $r^2,$ $r_A{}^2,$ $r_B{}^2,$ and $r_C{}^2$ are numbers in $k^\times$ equivalent to $d$ modulo $k^{\times 2}.$
\end{thm}
We prove Theorem \ref{thm-sim} in Section \ref{sec-sim}.  
We also prove Theorem \ref{thm-trig} and provide a few examples of triangles with $k$-rational vertices and incenter in Section \ref{sec-trig}.

\label{sec-sim}
The following propositions are fundamental for simplices over $k.$ 
Let $O$ be the origin of $\mathbb R^n.$
\begin{prop}\label{prop-vol-sim}
In $\mathbb R^n,$ the volume $V$ of $n$-simplex over $k$ is $k$-rational.
\end{prop}
\begin{pf}
The volume $V$ of $n$-simplex $A_0A_1\cdots A_n$ over $k$ is given by 
\[ V = \frac{1}{n!}|\det (\overrightarrow{A_0A_1}\ \cdots\ \overrightarrow{A_0A_j}\ \cdots\ \overrightarrow{A_0A_n})|\] 
(see \cite{Ste66}), which implies $V \in k.$
\end{pf}
\begin{prop}\label{prop-rat-pt}
In $\mathbb R^n,$ with respect to $n$-simplex $A_0A_1\cdots A_n$ over $k,$ a point $P$ is $k$-rational if and only if $P$ has barycentric coordinates $(\lambda _0:\lambda _1:\cdots :\lambda _n)$ such that 
\begin{equation} 
\frac{\lambda _0}{\sum _{i = 0}^n\lambda _i},\ \frac{\lambda _1}{\sum _{i = 0}^n\lambda _i},\ \dots,\ \frac{\lambda _n}{\sum _{i = 0}^n\lambda _i} \in k. \label{eq-rat} 
\end{equation} 
In particular, if a point $P$ has barycentric coordinates $(\lambda _0:\lambda _1:\cdots :\lambda _n)$ such that $\lambda _0,$ $\lambda _1,$ $\dots,$ $\lambda _n \in k,$ then $P$ is $k$-rational.
\end{prop}
\begin{pf}
If $P \in k^n,$ then $P$ has barycentric coordinates $(\lambda _0:\lambda _1:\cdots :\lambda _n)$ such that \eqref{eq-rat} by letting $\lambda _i$ be the volume of the $n$-simplex with vertices $P$ and $A_j$ $(j \in \{ 0,1,\dots,n\}\setminus\{ i\})$ for each $i \in \{ 0,1,\dots,n\},$ where $\lambda _0,$ $\lambda _1,$ $\dots,$ $\lambda _n \in k$ by Proposition \ref{prop-vol-sim}.\par
Conversely, if $P$ has barycentric coordinates $(\lambda _0:\lambda _1:\cdots :\lambda _n)$ such that \eqref{eq-rat}, then $P \in k^n,$ since we have 
\[\overrightarrow{OP} = \frac{\sum_{i = 0}^n\lambda _i\overrightarrow{OA_i}}{\sum_{i = 0}^n\lambda _i}\] 
by definition of barycentric coordinates.\par
The second statement follows immediately from the first. 
\end{pf}
We are now ready to prove Theorem \ref{thm-sim}.
\begin{pf}[Proof of Theorem \ref{thm-sim}]
The incenter $I$ has barycentric coordinates 
\[ I = (a_0:a_1:\cdots :a_n).\]\par 
First, (S1) implies (S2) by Theorem \ref{thm-ang}, since $I$ is the intersection point of the bisectors of $\angle A_iA_hA_j$ $(h \neq i \neq j \neq h).$\par
Conversely, if (S2) holds, then there exist positive numbers $a_{0,0},$ $a_{1,0},$ $\dots,$ $a_{n,0} \in k$ such that $a_0 = a_{0,0}\sqrt d,$ $a_1 = a_{1,0}\sqrt d,$ $\dots,$ $a_n = a_{n,0}\sqrt d,$ which imply 
\[\frac{a_i}{a_0+a_1+\cdots +a_n} = \frac{a_{i,0}}{a_{0,0}+a_{1,0}+\cdots +a_{n,0}} \in k\] 
for each $i \in \{ 0,1,\dots,n\}$ and therefore $I \in k^n.$\par
The latter statement follows immediately from the former.
\end{pf}
\begin{eg}
The incenter of a given Heronian tetrahedron over $k$ is $k$-rational.
\end{eg}
\begin{eg}
Let $p,$ $q,$ $r \in k^\times.$ 
The equifacial tetrahedron with vertices $(p,q,r),$ $(p,-q,-r),$ $(-p,q,-r),$ and $(-p,-q,r)$ has a $k$-rational incenter at $(0,0,0).$
\end{eg}
Let $[XYZ]$ denote the area of triangle $XYZ.$
\begin{eg}
Let $p,$ $q \in k$ with $p \neq 3q$ and $p > 0.$ 
Consider the right regular triangular pyramid $ABCD$ with $A = (p,0,0),$ $B = (0,p,0),$ $C = (0,0,p),$ and $D = (q,q,q).$ 
Since $\overrightarrow{DB} = (q,q-p,q),$ $\overrightarrow{DC} = (q,q,q-p),$ and $\overrightarrow{DB}\times\overrightarrow{DC} = p(p-2q,q,q),$ we have $[BCD] = (1/2)|\overrightarrow{DB}\times\overrightarrow{DC}| = (p/2)\sqrt{(p-2q)^2+2q^2}.$ 
Similarly, we have $[CDA] = [DAB] = (p/2)\sqrt{(p-2q)^2+2q^2}.$ 
Furthermore, since triangle $ABC$ is the regular triangle with side length $p\sqrt 2,$ we have $[ABC] = (\sqrt 3/4)\cdot (p\sqrt 2)^2 = p^2\sqrt 3/2.$ 
Therefore, tetrahedron $ABCD$ has a $k$-rational incenter $I$ if and only if 
\[ (p-2q)^2+2q^2 \equiv 3 \pmod{k^{\times 2}}.\] 
If there exists a positive number $r \in k$ such that 
\[ (p-2q)^2+2q^2 = 3r^2,\] 
then we have 
\[ [BCD]:[CDA]:[DAB]:[ABC] = \frac{pr}{2}\sqrt 3:\frac{pr}{2}\sqrt 3:\frac{pr}{2}\sqrt 3:\frac{p^2}{2}\sqrt 3 = r:r:r:p\] 
and 
\[\overrightarrow{OI} = \frac{r(p,0,0)+r(0,p,0)+r(0,0,p)+p(q,q,q)}{r+r+r+p} = \frac{p(q+r)}{p+3r}(1,1,1),\] 
which implies $I$ is $k$-rational. 
For example, tetrahedron $ABCD$ with $A = (7,0,0),$ $B = (0,7,0),$ $C = (0,0,7),$ and $D = (1,1,1)$ has a rational incenter $I = (7/4,7/4,7/4),$ since $(7-2\cdot 1)^2+2\cdot 1^2 = 3\cdot 3^2.$
\end{eg}

\label{sec-trig}
In this section, we consider a few centers of triangle $ABC$ over $k$ with side lengths $BC = a,$ $CA = b,$ and $AB = c,$ perimeter $a+b+c = 2s,$ and area $\Delta.$ 
The following propositions are fundamental.
\begin{prop}\label{prop-isom}
In $\mathbb R^2,$ with respect to triangle $ABC$ over $k,$ the isotomic conjugate point $Q$ of a given $k$-rational point $P$ is also $k$-rational.
\end{prop}
\begin{pf}
Suppose that $P$ has normalized barycentric coordinates $(\lambda :\mu :\nu ).$ 
Then $Q$ has barycentric coordinates $(1/\lambda :1/\mu :1/\nu ).$ 
Thus, $P \in k^2$ implies that $\lambda,$ $\mu,$ $\nu \in k,$ and $1/\lambda,$ $1/\mu,$ $1/\nu \in k,$ and therefore $Q \in k^2.$
\end{pf}
\begin{prop}\label{prop-isog}
In $\mathbb R^2,$ with respect to triangle $ABC$ over $k,$ the isogonal conjugate point $Q$ of a given $k$-rational point $P$ is also $k$-rational.
\end{prop}
\begin{pf}
Suppose that $P$ has normalized barycentric coordinates $(\lambda :\mu :\nu ).$ 
Then $Q$ has barycentric coordinates $(a^2/\lambda :b^2/\mu :c^2/\nu ).$ 
Thus, $P \in k^2$ implies that $\lambda,$ $\mu,$ $\nu \in k,$ and $a^2/\lambda,$ $b^2/\mu,$ $c^2/\nu \in k,$ and therefore $Q \in k^2.$
\end{pf}
\begin{prop}
In $\mathbb R^2,$ the centroid $G,$ the Lemoine point $L,$ the circumcenter $E,$ and the orthocenter $H$ of triangle $ABC$ over $k$ are $k$-rational.
\end{prop}
\begin{pf}
As is well-known (see \cite{ETC}), the points $G,$ $L,$ $E,$ and $H$ have barycentric coordinates 
\begin{align*} 
G &= (1:1:1), \\ 
L &= (a^2:b^2:c^2), \\ 
E &= (a^2(b^2+c^2-a^2):b^2(c^2+a^2-b^2):c^2(a^2+b^2-c^2)), \\ 
H &= \left(\frac{1}{b^2+c^2-a^2}:\frac{1}{c^2+a^2-b^2}:\frac{1}{a^2+b^2-c^2}\right). 
\end{align*} 
Since $a^2,$ $b^2,$ $c^2 \in k,$ all of these coordinates lie in $k,$ which implies $G,$ $L,$ $E,$ $H \in k^2.$
\end{pf}
\begin{prop}
In $\mathbb R^2,$ the circumradius $R$ and the inradius $r$ of Heronian triangle $ABC$ over $k$ lie in $k.$
\end{prop}
\begin{pf}
If $a,$ $b,$ $c,$ $\Delta \in k,$ then $R,$ $r \in k$ since $\Delta = abc/4R = rs$ (see \cite[Section 1.5]{Cox89}).\qedhere
\end{pf}
We are now ready to prove Theorem \ref{thm-trig}.
\begin{pf}[Proof of Theorem \ref{thm-trig}]
As is well-known (see \cite{ETC}), the points $I,$ $I_A,$ $I_B,$ $I_C,$ and $Na$ have barycentric coordinates 
\begin{align*} 
I &= (a:b:c), \\ 
I_A &= (-a:b:c), \quad I_B = (a:-b:c), \quad I_C = (a:b:-c), \\ 
Na & = (s-a:s-b:s-c). 
\end{align*}\par
It follows from Theorem \ref{thm-sim} that $I \in k^2$ and \eqref{eq-trig} are equivalent.\par
We prove that $I \in k^2$ and $I_A \in k^2$ are equivalent. 
The condition $I \in k^2$ is equivalent to $a/2s,$ $b/2s,$ $c/2s \in k,$ and $-a/2(s-a),$ $b/2(s-a),$ $c/2(s-a) \in k,$ and therefore $I_A \in k^2.$ 
Here, we used the identities 
\[\left(\frac{a}{2s}\right) ^{-1}-\left(\frac{a}{2(s-a)}\right) ^{-1} = 2, \quad \left(\frac{b}{2s}\right) ^{-1}-\left(\frac{b}{2(s-a)}\right) ^{-1} = \frac{2a}{b}, \quad\text{and}\quad \left(\frac{c}{2s}\right) ^{-1}-\left(\frac{c}{2(s-a)}\right) ^{-1} = \frac{2a}{c}.\] 
Similarly, the condition $I \in k^2$ is equivalent to $I_B \in k^2,$ and $I_C \in k^2.$\par
We prove that $Na \in k^2$ implies $I \in k^2.$ 
If $Na \in k^2,$ then $(s-a)/s,$ $(s-b)/s,$ $(s-c)/s \in k$ since $(s-a)+(s-b)+(s-c) = s.$ 
This implies that $a/2s,$ $b/2s,$ $c/2s \in k,$ and $I \in k^2.$ 
The converse is also true.\par
Furthermore, $Ge \in k^2$ and $Na \in k^2$ are equivalent, since $Ge$ and $Na$ are isotomic to each other.\par
In addition, if \eqref{eq-trig} holds, then there exist positive numbers $a_0,$ $b_0,$ $c_0,$ $d \in k$ such that $a = a_0\sqrt d,$ $b = b_0\sqrt d,$ and $c = c_0\sqrt d,$ which imply $2s = (a_0+b_0+c_0)\sqrt d,$ $2(s-a) = (b_0+c_0-a_0)\sqrt d,$ $2(s-b) = (c_0+a_0-b_0)\sqrt d,$ $2(s-c) = (a_0+b_0-c_0)\sqrt d,$ and therefore $r^2,$ $r_A{}^2,$ $r_B{}^2,$ and $r_C{}^2$ are numbers in $k^\times$ equivalent to $d$ modulo $k^{\times 2},$ since $\Delta \in k$ and $\Delta = rs = r_A(s-a) = r_B(s-b) = r_C(s-c)$ (see \cite[Section 1.5]{Cox89}).  
This implies that triangle $ABC$ is similar to the Heronian triangle over $k$ with side lengths $a_0,$ $b_0,$ and $c_0,$ and area $\Delta /d.$
\end{pf}
From Theorem \ref{thm-trig}, we obtain the following construction method for every triangle over $k$ with $k$-rational incenter.
\begin{cor}
In $\mathbb R^2,$ every triangle $ABC$ over $k$ with $k$-rational incenter can be constructed by the following steps.\par
{\tt Step 1.} 
Choose a positive number $d \in k.$\par
{\tt Step 2.} 
Choose solutions $(x_1,x_2,x_3) = (u_1,u_2,u_3),$ $(v_1,v_2,v_3),$ $(w_1,w_2,w_3)$ of $x_1{}^2+x_2{}^2 = dx_3{}^2$ in $k$ such that $\bm{u} = (u_1,u_2),$ $\bm{v} = (v_1,v_2),$ and $\bm{w} = (w_1,w_2)$ are pairwise linearly independent over $k.$\par
{\tt Step 3.} 
Find the intersection point $C_0$ of the line passing through $B_0 = (w_1,w_2)$ and parallel to $\bm{u}$ and the line connecting $O$ and $(v_1,v_2).$\par
{\tt Step 4.} 
Translate triangle $OB_0C_0$ by a certain vector in $k^2.$
\end{cor}
\begin{pf}
Consider triangle $ABC$ over $k$ with vertices $A = (a_1,a_2),$ $B = (b_1,b_2),$ and $C = (c_1,c_2),$ and $k$-rational incenter. 
Since 
\[ |\overrightarrow{BC}|^2 \equiv |\overrightarrow{CA}|^2 \equiv |\overrightarrow{AB}|^2 \pmod{k^{\times 2}}\] 
by Theorem \ref{thm-trig}, there exist numbers $u_3,$ $v_3,$ $w_3,$ $d \in k$ such that $d > 0$ and $(x_1,x_2,x_3) = (c_1-b_1,c_2-b_2,u_3),$ $(a_1-c_1,a_2-c_2,v_3),$ $(b_1-a_1,b_2-a_2,w_3)$ are solutions of $x_1{}^2+x_2{}^2 = dx_3{}^2$ in $k.$ 
Therefore, let $\bm{u} = \overrightarrow{BC},$ $\bm{v} = \overrightarrow{CA},$ and $\bm{w} = \overrightarrow{AB},$ which are pairwise linearly independent over $k.$ 
The line passing through $B_0 = (b_1-a_1,b_2-a_2)$ and parallel to $\bm{u}$ and the line connecting $O$ and $(a_1-c_1,a_2-c_2)$ intersect at $C_0 = (c_1-a_1,c_2-a_2).$ 
Triangle $ABC$ can be obtained by translating triangle $OB_0C_0$ by vector $\overrightarrow{OA} = (a_1,a_2).$
\end{pf}
\begin{eg}
In the following cases, the centroid $G,$ the Lemoine point $L,$ the circumcenter $E,$ the orthocenter $H,$ the incenter $I,$ the excenters $I_A,$ $I_B,$ and $I_C,$ the Gergonne point $Ge,$ and the Nagel point $Na$ of triangle $ABC$ are $k$-rational. 
For readers' convenience, we add the values of the vectors $\bm{u} = \overrightarrow{BC},$ $\bm{v} = \overrightarrow{CA},$ and $\bm{w} = \overrightarrow{AB},$ the side lengths $a,$ $b,$ and $c,$ the inradius $r,$ the exradii $r_A,$ $r_B,$ and $r_C,$ the positive algebraic integer $d \in O_k$ such that $a^2 \equiv b^2 \equiv c^2 \equiv d \pmod{k^{\times 2}},$ and the area $\Delta$ (see Figure 2 for the example in the middle column).
\begin{center}\begin{tabular}{|c||c|c|c|} \hline 
$k$ & $\mathbb Q$ & $\mathbb Q$ & $\mathbb Q(\sqrt 2)$ \\ \hline 
